def word_asr_8 (a : word8) (n : Nat) : word8 :=
  if n = 0 then a
  else if n < 8 then (a >>> n.toUInt8) ||| (if a &&& 0x80 != 0 then (0xFF : word8) <<< (8 - n).toUInt8 else 0)
  else if a &&& 0x80 != 0 then 0xFF else 0

def word_asr_64 (a : word64) (n : Nat) : word64 :=
  if n = 0 then a
  else if n < 64 then (a >>> n.toUInt64) ||| (if a &&& 0x8000000000000000 != 0 then (0xFFFFFFFFFFFFFFFF : word64) <<< (64 - n).toUInt64 else 0)
  else if a &&& 0x8000000000000000 != 0 then 0xFFFFFFFFFFFFFFFF else 0
